<template><div><PageHeader title="Certificates" description="Generate, issue and verify completion certificates."><template #actions><button class="btn secondary" @click="push('Certificate template editor opened.')">Manage templates</button><button class="btn primary" @click="generate">Generate certificate</button></template></PageHeader><div class="cards-4"><StatCard label="Issued this month" value="84" change="12% vs last month" icon="▱" accent="green"/><StatCard label="Pending" value="7" change="Needs review" icon="◷" accent="orange"/><StatCard label="Verified" value="1,984" change="All time" icon="✓" accent="blue"/><StatCard label="Revoked" value="2" change="This year" icon="!" accent="purple"/></div><div class="card" style="margin-top:18px"><div class="toolbar"><div class="toolbar-left"><input class="input search-input" placeholder="Search certificate ID or learner..."><select class="select"><option>All statuses</option><option>Issued</option><option>Pending</option><option>Revoked</option></select></div></div><DataTable :headers="['Certificate','Learner','Course','Issued','Status','']"><tr v-for="c in certificates" :key="c.id"><td><strong>{{c.number}}</strong></td><td><div class="row-person"><Avatar :name="c.learner" size="sm"/><strong>{{c.learner}}</strong></div></td><td>{{c.course}}</td><td>{{c.issued}}</td><td><StatusBadge :status="c.status"/></td><td><button class="btn secondary small">Open</button></td></tr></DataTable></div></div></template>
<script setup lang="ts">import PageHeader from '../components/PageHeader.vue';import StatCard from '../components/StatCard.vue';import DataTable from '../components/DataTable.vue';import Avatar from '../components/Avatar.vue';import StatusBadge from '../components/StatusBadge.vue';import {certificates} from '../data/mock';import {useToast} from '../composables/useToast';const {push}=useToast();function generate(){push('Certificate generation workflow opened.')}</script>
